import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int small = 0;
        int medium = 0;

        for (int i = 0; i < n; i++) {
            int t = sc.nextInt();
            if (t == 1) {
                small++;
            } else {
                medium++;
            }
        }

        int p = sc.nextInt();
        int m = sc.nextInt();

        if (small <= p && medium <= m) {
            System.out.println("S");
        } else {
            System.out.println("N");
        }

        sc.close();
    }
}
